// Green Matcha by MJType (www.mjtype.com), used for the YourDramaList logo text on Connect and in the
// app's opening animation. Served from this site so it loads with the page.
const encoded="";
let bytes:Uint8Array|undefined;
export const LOGO_FONT_PATH="/assets/green-matcha-v1.otf";
export function logoFont(){bytes??=Uint8Array.from(atob(encoded),c=>c.charCodeAt(0));return new Response(bytes,{headers:{"content-type":"font/otf","cache-control":"public,max-age=31536000,immutable","x-content-type-options":"nosniff"}});}
